BEGIN;CREATE TABLE IF NOT EXISTS assignment_cancellations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,assignment_id uuid NOT NULL REFERENCES work_assignments(id) ON DELETE RESTRICT,initiator_identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE RESTRICT,reason text NOT NULL CHECK(char_length(reason) BETWEEN 1 AND 1000),initiator_kind text NOT NULL CHECK(initiator_kind IN('professional','company')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(assignment_id));ALTER TABLE assignment_cancellations ENABLE ROW LEVEL SECURITY;ALTER TABLE assignment_cancellations FORCE ROW LEVEL SECURITY;CREATE POLICY assignment_cancellations_tenant ON assignment_cancellations USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT ON assignment_cancellations TO app_runtime;COMMIT;